+#[test]
+fn version_batch_authenticates_once_binds_results_rejects_replay_and_preserves_old_route() {
+    let h = Harness::start("version-batch-wire");
+    let cred = h.setup_account();
+    let entries = vec![batch_entry(71), batch_entry(72)];
+    let body = batch_body(entries.clone());
+    // Establish the first-authentication seen event before counting version frames.
+    assert_eq!(
+        Req::get("/v1/account").sign(&cred, NOW).send(h.addr).status,
+        200
+    );
+    let head = h.app.store.head_seq();
+    let unsigned = Req::post("/v1/versions/batch").body(&body).send(h.addr);
+    assert_eq!(unsigned.status, 401);
+    assert_eq!(h.app.store.head_seq(), head);
+    let sent_nonce = nonce();
+    let digest = hex::encode(&sha256::sha256(body.as_bytes()));
+    let send = || {
+        Req::post("/v1/versions/batch")
+            .body(&body)
+            .sign_with(&cred, NOW, &sent_nonce, &digest)
+            .send(h.addr)
+    };
+    let response = send();
+    assert_eq!(response.status, 200, "{}", response.text());
+    let json = response.json();
+    let results = json.get("results").and_then(Value::as_array).unwrap();
+    assert_eq!(results.len(), 2);
+    for (input, result) in entries.iter().zip(results) {
+        assert_eq!(result.get("file_id"), input.get("file_id"));
+        assert_eq!(
+            result.get("posted_version_id"),
+            input.get("version").unwrap().get("version_id")
+        );
+        assert_eq!(result.get("status").and_then(Value::as_u64), Some(201));
+        let file = input.get("file_id").and_then(Value::as_str).unwrap();
+        let held = Req::get(&format!("/v1/files/{file}"))
+            .sign(&cred, NOW)
+            .send(h.addr);
+        assert_eq!(held.status, 200);
+        assert_eq!(
+            held.json().get("heads"),
+            result.get("body").unwrap().get("heads")
+        );
+        let original = Req::post(&format!("/v1/files/{file}/versions"))
+            .body(&input.get("version").unwrap().to_string())
+            .sign(&cred, NOW)
+            .send(h.addr);
+        assert_eq!(
+            original.status, 200,
+            "old route recognises each durable version"
+        );
+    }
+    let replay = send();
+    assert_eq!(replay.status, 401);
+    assert_eq!(replay.code(), "replayed_nonce");
+    assert_eq!(h.app.store.head_seq(), crate::types::Seq(head.0 + 4));
+}
