+    let h = Harness::start("version-batch-invalid");
+    let cred = h.setup_account();
+    // Establish the first-authentication seen event before counting version frames.
+    assert_eq!(
+        Req::get("/v1/account").sign(&cred, NOW).send(h.addr).status,
+        200
+    );
+    let head = h.app.store.head_seq();
+    let inputs = vec![
+        vec![],
+        vec![batch_entry(1), batch_entry(1)],
+        (1..=33).map(batch_entry).collect(),
+        vec![batch_entry(1), Value::Null],
+    ];
+    for items in inputs {
+        let response = Req::post("/v1/versions/batch")
+            .body(&batch_body(items))
+            .sign(&cred, NOW)
+            .send(h.addr);
+        assert_eq!(response.status, 400, "{}", response.text());
+        assert_eq!(h.app.store.head_seq(), head);
+    }
+    // The byte reservation refuses at the headers, before reading a body.
+    // A full-body helper would get BrokenPipe when that early refusal closes.
+    let request = Req::post("/v1/versions/batch").sign(&cred, NOW);
+    let mut wire = String::from(
+        "POST /v1/versions/batch HTTP/1.1\r\nHost: 127.0.0.1\r\nContent-Length: 4194305\r\nConnection: close\r\n",
+    );
+    for (name, value) in request.headers {
+        wire.push_str(&format!("{name}: {value}\r\n"));
+    }
+    wire.push_str("\r\n");
+    let mut stream = TcpStream::connect(h.addr).unwrap();
+    stream
+        .set_read_timeout(Some(Duration::from_secs(5)))
+        .unwrap();
+    stream.write_all(wire.as_bytes()).unwrap();
+    let mut received = Vec::new();
+    stream.read_to_end(&mut received).unwrap();
+    let response = Res::parse(&received);
+    assert_eq!(response.status, 413);
+    assert_eq!(h.app.store.head_seq(), head);
